function validarAperturaCruce(cruce){const incidentes=[...(ultimoFlujo?.porNodo.get(Number(cruce.nodo))||ultimoFlujo?.porNodo.get(String(cruce.nodo))||[])].filter(e=>e.g3e_fno===19000);if(incidentes.length!==4||!Array.isArray(cruce.grupos)||cruce.grupos.length!==2)return{ok:false,mensaje:"El punto debe corresponder a un cruce de exactamente cuatro líneas."};const temporal={id:String(cruce.nodo),nodo:String(cruce.nodo),codigo:cruce.codigo||String(cruce.nodo),circuito:cruce.circuito,punto:cruce.punto,grupos:cruce.grupos};operacionesVirtuales.cruces.set(String(cruce.nodo),temporal);const flujo=calcularEnergia(ultimos);operacionesVirtuales.cruces.delete(String(cruce.nodo));const porFid=new Map(incidentes.map(e=>[String(e.g3e_fid),e])),componentes=[];for(const grupo of cruce.grupos){const linea=porFid.get(String(grupo[0]));if(!linea)continue;const otro=String(linea.nodo1)===String(cruce.nodo)?linea.nodo2:linea.nodo1;componentes.push(componenteDesdeNodo(otro,"",flujo));}const vivos=componentes.filter(x=>x.energizado),muertos=componentes.filter(x=>!x.energizado&&(x.cargas.transformadores+x.cargas.fronteras>0||x.cargas.usuarios>0)),resumen=componentes.map((x,i)=>"Corredor "+(i+1)+" ("+cruce.grupos[i].map(fid=>porFid.get(String(fid))?.codigo||fid).join(" ↔ ")+"): "+textoLado(x)).join(". ");if(vivos.length===0)return{ok:true,mensaje:"Separaci\u00f3n permitida: ambos corredores est\u00e1n sin tensi\u00f3n. La carga conectada permanece desenergizada. "+resumen};if(vivos.length>1)return{ok:false,mensaje:"MANIOBRA BLOQUEADA: ambos corredores conservan tensi\u00f3n. "+resumen};if(muertos.length)return{ok:false,mensaje:"MANIOBRA BLOQUEADA: con un corredor energizado, el corredor sin tensi\u00f3n conserva carga conectada. "+resumen};return{ok:true,mensaje:"Separaci\u00f3n permitida: un corredor est\u00e1 energizado y el corredor sin tensi\u00f3n no conserva carga. "+resumen};}
const validarAperturaCruceTopologica=validarAperturaCruce;
function impactoTopologicoAperturaCruce(cruce){const antes=calcularEnergia(ultimos),clave=String(cruce.nodo),anterior=operacionesVirtuales.cruces.get(clave),temporal={id:clave,nodo:clave,codigo:cruce.codigo||clave,circuito:cruce.circuito,punto:cruce.punto,grupos:cruce.grupos};operacionesVirtuales.cruces.set(clave,temporal);const despues=calcularEnergia(ultimos);if(anterior)operacionesVirtuales.cruces.set(clave,anterior);else operacionesVirtuales.cruces.delete(clave);let transformadores=0;const usuarios=new Set(),detalle=[];for(const e of antes.elementos.values()){if(Number(e.g3e_fno)!==20400||estadoElemento(e)==="OPEN")continue;const fid=String(e.g3e_fid),tenia=(antes.procedencia.get(fid)||new Set()).size>0,conserva=(despues.procedencia.get(fid)||new Set()).size>0;if(tenia&&!conserva){transformadores++;detalle.push(e.codigo||fid);for(const id of usuariosActivos(e).keys())usuarios.add(id);}}return{transformadores,usuarios:usuarios.size,detalle,antes,despues};}
validarAperturaCruce=cruce=>{const impacto=impactoTopologicoAperturaCruce(cruce);if(impacto.transformadores===0)return{ok:true,mensaje:"Separación permitida por análisis topológico: ninguna carga energizada depende del cruce; todos los transformadores conservan su fuente después de separar los corredores."};const resultado=validarAperturaCruceTopologica(cruce);return{...resultado,ok:false,mensaje:"MANIOBRA BLOQUEADA POR DEPENDENCIA TOPOLÓGICA: abrir el cruce dejaría sin fuente "+impacto.transformadores+" transformador(es) y "+impacto.usuarios+" usuario(s). Transformadores dependientes: "+impacto.detalle.slice(0,12).join(", ")+(impacto.detalle.length>12?"…":"")+". "+resultado.mensaje};};
async function abrirCruceVirtual(cruce){let seguridad={ok:true,mensaje:"Estado final dibujado; la IA agregará las maniobras necesarias para descargar el cruce."};if(modoGrabacionManiobras){seguridad=validarAperturaCruce(cruce);const flujo=validarFlujoAperturaCruce(cruce);if(seguridad.ok&&flujo)seguridad={...seguridad,mensaje:seguridad.mensaje+" "+flujo.mensaje};}if(!seguridad.ok){alert(seguridad.mensaje);setProceso(seguridad.mensaje);return;}const id=String(cruce.nodo),relacion=codigoParesCruce(cruce.grupos),codigo="Cruce "+relacion;operacionesVirtuales.cruces.set(id,{id,nodo:id,codigo,circuito:cruce.circuito,punto:cruce.punto,grupos:cruce.grupos,lineas:cruce.lineas.map(e=>String(e.g3e_fid))});registrarManiobra("Separar cruce aéreo",codigo,"OPEN",{grupos:cruce.grupos,punto:cruce.punto});await aplicarCambioVirtual("Cruce de cuatro líneas separado en "+relacion+". "+seguridad.mensaje);}
function resumenInterruptorNodo(item){return `<b>Interruptor provisional de nodo</b><br>${esc(item.codigo)}<br><b>Nodo GTECH:</b> ${esc(item.nodo)}<br><b>Estado:</b> ${esc(item.estado)}<br><button type="button" onclick="operarInterruptorNodo('${esc(item.id)}','${item.estado==="OPEN"?"CLOSED":"OPEN"}')">${item.estado==="OPEN"?"Cerrar":"Abrir"} interruptor</button><br><button type="button" onclick="retirarOperacionVirtual('node-switch','${esc(item.id)}')">Retirar maniobra</button>`;}window.operarInterruptorNodo=async(id,nuevo)=>{const equipo=operacionesVirtuales.interruptoresNodo.get(String(id));if(!equipo)return;equipo.estado=nuevo;registrarManiobra("Interruptor provisional de nodo",equipo.codigo,nuevo,{id:equipo.id,nodo:equipo.nodo,fidA:equipo.fidA,fidB:equipo.fidB});await aplicarCambioVirtual(`Interruptor provisional ${equipo.id} ${nuevo==="OPEN"?"abierto":"cerrado"} entre ${equipo.codigo}.`);};window.operarEnlaceVirtual=async(id,nuevo)=>{const enlace=operacionesVirtuales.enlaces.get(String(id));if(!enlace)return;const anterior=enlace.estado;let paresCierre=[];if(nuevo==="CLOSED"){const antes=calcularEnergia(ultimos);enlace.estado="CLOSED";const despues=calcularEnergia(ultimos),pares=paresNuevosParalelo(antes,despues),riesgos=pares.filter(x=>!x.mismaBarra);paresCierre=pares;if(riesgos.length&&!confirm(`ADVERTENCIA DE PARALELO\n\n${riesgos.map(x=>`${x.a} / ${x.b}`).join(", ")}\n\nDesea cerrar el interruptor provisional?`)){enlace.estado=anterior;return;}}else enlace.estado="OPEN";registrarManiobra("Interruptor provisional",enlace.codigo,nuevo,{id:enlace.id,paresParalelo:paresCierre});await aplicarCambioVirtual(`Interruptor provisional ${nuevo==="CLOSED"?"cerrado":"abierto"}.`);};
window.retirarOperacionVirtual=async(tipo,id)=>{const mapa=tipo==="corte"?operacionesVirtuales.cortesLinea:tipo==="enlace"?operacionesVirtuales.enlaces:tipo==="node-switch"?operacionesVirtuales.interruptoresNodo:tipo==="brakesafe"?operacionesVirtuales.brakesafes:operacionesVirtuales.cruces;if(tipo==="corte"){for(const[k,v]of mapa)if(v.id===id)mapa.delete(k);}else if(tipo==="brakesafe"){for(const[k,v]of mapa)if(v.id===id)mapa.delete(k);}else mapa.delete(String(id));await aplicarCambioVirtual("Maniobra virtual retirada.");};
function restaurarVirtuales(redibujar=true){operacionesVirtuales.cortesLinea.clear();operacionesVirtuales.enlaces.clear();operacionesVirtuales.interruptoresNodo.clear();operacionesVirtuales.cruces.clear();operacionesVirtuales.brakesafes.clear();operacionesVirtualesLayer.clearLayers();ayudasHerramientaLayer.clearLayers();herramientaMapa="";seleccionEnlace=null;document.querySelectorAll("[data-map-tool]").forEach(b=>b.classList.remove("active"));if(redibujar&&ultimos.length)return dibujarTodo(ultimos,false);}function copiaSerializable(valor){return JSON.parse(JSON.stringify(valor));}
