function textoClaveParalelo(valor){return String(valor||"").normalize("NFD").replace(/[\u0300-\u036f]/g,"").toUpperCase().replace(/[^A-Z0-9]/g,"");}
function subestacionClaveParalelo(valor){const limpia=String(valor||"").normalize("NFD").replace(/[\u0300-\u036f]/g,"").toUpperCase().replace(/^R\d+\s*[-_]?\s*S\s*\/?\s*E[\s._-]*/,"");return textoClaveParalelo(limpia);}
function claveParalelo(subA,celdaA,subB,celdaB){return [`${subestacionClaveParalelo(subA)}@${textoClaveParalelo(celdaA)}`,`${subestacionClaveParalelo(subB)}@${textoClaveParalelo(celdaB)}`].sort().join("||");}
function claveParaleloFuentes(a,b){const pa=String(a||"").split("@"),pb=String(b||"").split("@");return claveParalelo(pa[1],pa[0],pb[1],pb[0]);}
function paraleloAutorizado(a,b,par=null){if(par?.mismaBarra)return true;if(typeof paraleloNivelSuperiorIA==="function"&&paraleloNivelSuperiorIA(a,b,par))return true;const key=claveParaleloFuentes(a,b);return paralelosPermitidos.some(x=>x.activo&&claveParalelo(x.subestacion_a,x.celda_a_codigo,x.subestacion_b,x.celda_b_codigo)===key);}
function paresNuevosParalelo(antes,despues){const pares=new Map();despues.procedencia.forEach((feeds,fid)=>{const prev=antes.procedencia.get(fid)||new Set(),lista=[...feeds];if(lista.length<=1||prev.size>1)return;for(let i=0;i<lista.length;i++)for(let j=i+1;j<lista.length;j++){const subA=String(lista[i]).split("@")[1]||"",subB=String(lista[j]).split("@")[1]||"";if(!subA||lista[i]===lista[j])continue;const fuenteA=despues.semillas.find(x=>x.key===lista[i]),fuenteB=despues.semillas.find(x=>x.key===lista[j]),barraA=fuenteA?.barraFid?String(fuenteA.barraFid):"",barraB=fuenteB?.barraFid?String(fuenteB.barraFid):"",mismaBarra=subestacionClaveParalelo(subA)===subestacionClaveParalelo(subB)&&barraA&&barraA===barraB,key=claveParaleloFuentes(lista[i],lista[j]);pares.set(key,{a:lista[i],b:lista[j],barraA,barraB,mismaBarra:Boolean(mismaBarra)});}});return [...pares.values()];}async function cargarParalelosPermitidos(){try{const r=await fetch(APP.adminParalelos),d=await r.json();if(!r.ok)throw new Error(d.error||"No fue posible consultar los paralelos permitidos.");paralelosPermitidos=d.paralelos||[];return paralelosPermitidos;}catch(error){setProceso(error.message);return paralelosPermitidos;}}

