window.actualizarCircuito=async key=>{const indice=ultimos.findIndex(x=>claveItem(x.item)===key);if(indice<0)return;const actual=ultimos[indice],grupo=capasPorCircuito.get(key);setProceso(`Actualizando ${actual.item.circuito} desde GTECH y SAC...`,true);try{const q=new URLSearchParams({subestacion:actual.item.subestacion,fid:actual.item.fid,actualizar:"1"}),r=await fetch(`${APP.trazado}?${q}`),d=await r.json();if(!r.ok)throw new Error(d.error||"No fue posible actualizar");ultimos[indice]={...actual,data:d,error:null};if(grupo){capas.removeLayer(grupo);capasPorCircuito.delete(key);}await dibujarTodo(ultimos,false,new Set([key]));setProceso(`${actual.item.circuito} actualizado y guardado en JSON.`);}catch(error){setProceso(error.message);}};
function estadoElemento(e){return e?.estado_simulado||e?.estado_operativo||e?.estado_estable||"CLOSED";}
function componenteDesdeNodo(nodo,fidExcluido,flujoAbierto,override={},cargasIgnoradas=new Set()){const visitados=new Set(),cola=[...(flujoAbierto.porNodo.get(nodo)||[])],cargas={transformadores:0,usuarios:0,fronteras:0},fuentes=new Set();while(cola.length){const e=cola.shift();if(!e)continue;const fid=String(e.g3e_fid);if(fid===fidExcluido||visitados.has(fid))continue;visitados.add(fid);const st=override[fid]||estadoElemento(e),esRaiz=flujoAbierto.semillas.some(x=>String(x.fid)===fid),bloqueado=(corte.has(e.g3e_fno)&&st==="OPEN")||operacionesVirtuales.cortesLinea.has(fid)||operacionesVirtuales.brakesafes.get(fid)?.estado==="OPEN";if(!bloqueado)for(const f of flujoAbierto.procedencia.get(fid)||[])fuentes.add(f);if(e.g3e_fno===20400&&st!=="OPEN"&&!cargasIgnoradas.has(fid)){cargas.transformadores++;cargas.usuarios+=usuariosActivos(e).size;}if(e.g3e_fno===18800&&e.frontera_externa&&st!=="OPEN"&&!cargasIgnoradas.has(fid))cargas.fronteras++;if(bloqueado||esRaiz)continue;for(const n of [e.nodo1,e.nodo2].filter(Boolean)){for(const v of flujoAbierto.porNodo.get(n)||[])if(crucePermitePaso(n,fid,String(v.g3e_fid))&&String(v.g3e_fid)!==fidExcluido&&!visitados.has(String(v.g3e_fid)))cola.push(v);}}return{energizado:fuentes.size>0,fuentes,cargas,elementos:visitados};}
function tramoEnParalelo(e){const fidObjetivo=String(e.g3e_fid),inicio=e.nodo1,meta=String(e.nodo2||"");if(!inicio||!meta)return false;const vistosNodos=new Set([String(inicio)]),vistosElementos=new Set(),cola=[String(inicio)],raices=new Set((ultimoFlujo?.semillas||[]).map(x=>String(x.fid)));while(cola.length){const nodo=cola.shift();if(nodo===meta)return true;for(const v of ultimoFlujo?.porNodo.get(Number(nodo))||ultimoFlujo?.porNodo.get(nodo)||[]){const vf=String(v.g3e_fid);if(vf===fidObjetivo||vistosElementos.has(vf))continue;vistosElementos.add(vf);const st=estadoElemento(v),bloqueado=(corte.has(v.g3e_fno)&&st==="OPEN")||operacionesVirtuales.cortesLinea.has(vf)||operacionesVirtuales.brakesafes.get(vf)?.estado==="OPEN";if(bloqueado||raices.has(vf))continue;for(const n of [v.nodo1,v.nodo2].filter(Boolean)){const nk=String(n);if(!vistosNodos.has(nk)){vistosNodos.add(nk);cola.push(nk);}}}}return false;}
function textoLado(lado){const nombres=[...lado.fuentes].map(x=>x.split("@")[0]).join(" + ")||"sin fuente";return `${lado.energizado?"con tension":"sin tension"} (${nombres}); ${lado.cargas.transformadores} trafo(s), ${lado.cargas.usuarios} usuario(s) y ${lado.cargas.fronteras} frontera(s)`;}
function validarSeccionamientoSinCarga(e,nuevo="OPEN"){if(!e)return{ok:false,mensaje:"No se encontro el elemento en la red dibujada."};const fid=String(e.g3e_fid),nodos=[e.nodo1,e.nodo2].filter(Boolean);if(nodos.length<2)return{ok:false,mensaje:"No se pueden determinar los dos extremos electricos del elemento."};const flujoPrevio=calcularEnergia(ultimos),cargasDeslastradas=new Set([...flujoPrevio.elementos.values()].filter(x=>(x.g3e_fno===20400||(x.g3e_fno===18800&&x.frontera_externa))&&!(flujoPrevio.procedencia.get(String(x.g3e_fid))?.size)).map(x=>String(x.g3e_fid))),flujoAbierto=calcularEnergia(ultimos,{[fid]:"OPEN"}),a=componenteDesdeNodo(nodos[0],fid,flujoAbierto,{},cargasDeslastradas),b=componenteDesdeNodo(nodos[1],fid,flujoAbierto,{},cargasDeslastradas),carga=x=>x.cargas.transformadores+x.cargas.fronteras>0||x.cargas.usuarios>0,resumen="Lado 1: "+textoLado(a)+". Lado 2: "+textoLado(b)+".";if(!a.energizado&&!b.energizado)return{ok:true,resumen,mensaje:"Operacion permitida: ambos extremos estan sin tension."};if(a.energizado&&b.energizado){if(nuevo==="CLOSED"&&(!carga(a)||!carga(b)))return{ok:true,resumen,mensaje:"Cierre permitido: ambos extremos tienen tension y uno de los lados no conserva carga conectada."};return{ok:false,resumen,mensaje:"MANIOBRA BLOQUEADA: ambos extremos tienen tension y conservan carga conectada. "+resumen};}const muerto=a.energizado?b:a;if(carga(muerto))return{ok:false,resumen,mensaje:"MANIOBRA BLOQUEADA: el lado sin tension conserva carga conectada. "+resumen};return{ok:true,resumen,mensaje:"Operacion permitida: un extremo tiene tension y el lado sin tension no tiene carga conectada."};}
const validarSeccionamientoPorComponentes=validarSeccionamientoSinCarga;
validarSeccionamientoSinCarga=(e,nuevo="OPEN")=>{if(!e||nuevo!=="OPEN")return validarSeccionamientoPorComponentes(e,nuevo);const fid=String(e.g3e_fid),antes=calcularEnergia(ultimos),despues=calcularEnergia(ultimos,{[fid]:"OPEN"});let transformadores=0;const usuarios=new Set(),detalle=[];for(const t of antes.elementos.values()){if(Number(t.g3e_fno)!==20400||estadoElemento(t)==="OPEN")continue;const id=String(t.g3e_fid),tenia=(antes.procedencia.get(id)||new Set()).size>0,conserva=(despues.procedencia.get(id)||new Set()).size>0;if(tenia&&!conserva){transformadores++;detalle.push(t.codigo||id);for(const u of usuariosActivos(t).keys())usuarios.add(u);}}if(transformadores===0)return{ok:true,resumen:"Impacto marginal: 0 transformadores.",mensaje:"Apertura permitida por análisis topológico: ninguna carga energizada depende de este corredor o línea en el estado actual."};const base=validarSeccionamientoPorComponentes(e,nuevo);return{...base,ok:false,mensaje:"MANIOBRA BLOQUEADA POR DEPENDENCIA TOPOLÓGICA: la apertura dejaría sin fuente "+transformadores+" transformador(es) y "+usuarios.size+" usuario(s). Transformadores dependientes: "+detalle.slice(0,12).join(", ")+(detalle.length>12?"…":"")+". "+base.mensaje};};
function validarAisladero(e,nuevo){const fid=String(e.g3e_fid),accion=nuevo==="CLOSED"?"cierre":"apertura",limite=Number(nuevo==="CLOSED"?reglasManiobra.corriente_max_cierre_aisladero_a:reglasManiobra.corriente_max_apertura_aisladero_a),nodos=[e.nodo1,e.nodo2].filter(Boolean),flujoAbierto=calcularEnergia(ultimos,{[fid]:"OPEN"}),lados=nodos.map(n=>componenteDesdeNodo(n,fid,flujoAbierto)),conCarga=x=>x.cargas.transformadores+x.cargas.fronteras>0||x.cargas.usuarios>0,vivos=lados.filter(x=>x.energizado),muertosConCarga=lados.filter(x=>!x.energizado&&conCarga(x));if(lados.length===2&&(vivos.length===0||(vivos.length===1&&muertosConCarga.length===0)))return{ok:true,mensaje:"Operacion permitida: la topologia confirma corriente de maniobra 0 A; "+accion+" con un extremo energizado y el otro sin carga."};const feeds=ultimoFlujo?.procedencia.get(fid)||new Set();if(!feeds.size)return{ok:true,mensaje:"Cortacircuito o aisladero sin tension: corriente calculada 0 A; "+accion+" permitida."};const dato=corrientesPorElemento.get(fid);if(!fechaCorrientesAnalisis||!dato)return{ok:false,mensaje:"MANIOBRA BLOQUEADA: la topologia no permite asegurar corriente 0 A. Ejecute el analisis diario para verificar la corriente antes de la "+accion+". Limite configurado: "+numeroEje(limite)+" A."};if(dato.paralelo)return{ok:false,mensaje:"MANIOBRA BLOQUEADA: no se pudo distribuir la corriente del cortacircuito o aisladero mientras el tramo esta en paralelo."};const maxima=Math.max(0,...dato.series.map(maximoSerie)),ok=maxima<=limite;return ok?{ok:true,mensaje:"Operacion permitida: corriente maxima calculada "+numeroEje(maxima)+" A (limite de "+accion+": "+numeroEje(limite)+" A)."}:{ok:false,mensaje:"MANIOBRA BLOQUEADA: corriente maxima calculada "+numeroEje(maxima)+" A. El limite de "+accion+" configurado es "+numeroEje(limite)+" A."};}
// El aisladero tiene capacidad de maniobra: puede abrir para deslastrar carga.
