// El perfil eléctrico necesita que SAC haya terminado y que cada tramo del árbol
// tenga una corriente explícita, incluso cuando el valor correcto sea 0 A.
const calcularCorrientesPorTramoConCeros=calcularCorrientesPorTramo;
calcularCorrientesPorTramo=function(ajustadas,cargas345=new Map()){
  calcularCorrientesPorTramoConCeros(ajustadas,cargas345);
  const porFuente=new Map(ajustadas.map(x=>[x.analisis.key,x]));
  for(const [fuenteKey,arbol] of arbolesAlimentador){
    const dato=porFuente.get(fuenteKey),base=dato?.corrienteAjustada;
    if(!base?.series?.length)continue;
    const tieneReparto=[...arbol.parent.keys()].some(fid=>{const d=corrientesPorElemento.get(String(fid));return d&&!d.paralelo&&Number(d.porcentaje)>0;});
    if(!tieneReparto){
      const pesos=new Map();
      for(const [fid] of arbol.parent){
        const carga=ultimoFlujo?.elementos.get(String(fid));
        if(carga?.g3e_fno!==20400||estadoElemento(carga)==="OPEN")continue;
        const capacidad=Number(carga.capacidad);
        pesos.set(String(fid),Number.isFinite(capacidad)&&capacidad>0?capacidad:1);
      }
      const total=[...pesos.values()].reduce((a,b)=>a+b,0),acumulado=new Map();
      if(total)for(const [carga,peso] of pesos){for(let fid=carga;fid;fid=arbol.parent.get(fid))acumulado.set(String(fid),(acumulado.get(String(fid))||0)+peso);}
      for(const [fid,peso] of acumulado){
        const e=ultimoFlujo?.elementos.get(String(fid));
        if(!e||(e.g3e_fno!==19000&&!corte.has(e.g3e_fno)))continue;
        const fraccion=peso/total,series=base.series.map(s=>({...s,puntos:(s.puntos||[]).map(p=>[p[0],Number(p[1])*fraccion])}));
        corrientesPorElemento.set(String(fid),{codigo:e.codigo||e.g3e_fid,alimentador:arbol.raiz?.circuito||fuenteKey.split("@")[0],alimentadorKey:fuenteKey,porcentaje:fraccion,series,metodoCarga:"CAPACIDAD_TRANSFORMADORES"});
      }
    }
    for(const [fid] of arbol.parent){
      const e=ultimoFlujo?.elementos.get(String(fid));
      if(!e||(e.g3e_fno!==19000&&!corte.has(e.g3e_fno))||corrientesPorElemento.has(String(fid)))continue;
      const series=base.series.map(s=>({...s,puntos:(s.puntos||[]).map(p=>[p[0],0])}));
      corrientesPorElemento.set(String(fid),{codigo:e.codigo||e.g3e_fid,alimentador:arbol.raiz?.circuito||fuenteKey.split("@")[0],alimentadorKey:fuenteKey,porcentaje:0,series,sinCarga:true});
    }
  }
};

async function asegurarSacAntesDelAnalisis(){
  const pendientes=ultimos.filter(x=>x?.data&&x.data.version_sac_activos!==1);
  if(!pendientes.length)return;
  const consultasExistentes=pendientes.map(x=>x.sacPromise).filter(Boolean);
  if(!consultasExistentes.length){
    measureStatus.textContent="Calculando con los datos ya cargados; no se harán nuevas consultas SAC.";
    return;
  }
  measureStatus.textContent=`Esperando ${consultasExistentes.length} consulta(s) ya iniciada(s), sin repetirlas...`;
  await Promise.allSettled(consultasExistentes);
  if(redibujadoSacPendiente){clearTimeout(redibujadoSacPendiente);redibujadoSacPendiente=null;await dibujarTodo(ultimos,false);}
}
const cargarGraficasMedidasConSac=cargarGraficasMedidas;
cargarGraficasMedidas=async function(){await asegurarSacAntesDelAnalisis();return cargarGraficasMedidasConSac();};
measureDraw?.addEventListener("click",cargarGraficasMedidas);measureRecalculate?.addEventListener("click",()=>{forzarRecalculoAnalisis=true;cargarGraficasMedidas();});

window.abrirVistaAnalisis=()=>{const vista=document.querySelector("#analysis-view"),body=document.querySelector("#analysis-view-body"),analisis=construirAnalisisAlimentadores();if(!vista||!body)return;prepararSelectorMedidas();if(!analisis){body.innerHTML='<div class="analysis-empty"><h2>Sin información</h2><p>Primero dibuje al menos un circuito.</p></div>';vista.hidden=false;return;}const alimentadores=analisis.alimentadores,desconectados=new Set(),trasladados=new Set(),recibidos=new Set(),trafos=new Set(),bloques345=new Set((analisis.transferencias||[]).filter(x=>x.tipo==="FRONTERA_345").map(x=>String(x.fid)));for(const a of alimentadores){a.usuariosDesconectados.forEach((_,id)=>desconectados.add(id));a.usuariosTrasladados.forEach((_,id)=>trasladados.add(id));a.usuariosRecibidos.forEach((_,id)=>recibidos.add(id));[a.trafosTrasladados,a.trafosRecibidos,a.trafosDesconectados].forEach(set=>set.forEach(id=>trafos.add(id)));}body.innerHTML=`<div class="analysis-overview"><article><span>Alimentadores dibujados</span><b>${alimentadores.length}</b></article><article><span>Dispositivos maniobrados</span><b>${analisis.maniobrados.length}</b></article><article><span>Transformadores / bloques 34,5 kV afectados</span><b>${trafos.size.toLocaleString("es-CO")} / ${bloques345.size.toLocaleString("es-CO")}</b></article><article><span>Usuarios trasladados / recibidos</span><b>${trasladados.size.toLocaleString("es-CO")} / ${recibidos.size.toLocaleString("es-CO")}</b></article><article><span>Usuarios desconectados</span><b>${desconectados.size.toLocaleString("es-CO")}</b></article></div>${alimentadores.map(htmlAlimentador).join("")||'<div class="analysis-empty"><h2>No hay movimientos</h2><p>La red conserva su alimentación original y no hay dispositivos maniobrados.</p></div>'}`;vista.hidden=false;window.scrollTo(0,0);};
window.cerrarVistaAnalisis=()=>{const vista=document.querySelector("#analysis-view");if(vista)vista.hidden=true;map.invalidateSize();};
function nombreAccion(estado){return estado==="CLOSED"?"Cerrar":"Abrir";}
function invertirEstado(estado){return estado==="CLOSED"?"OPEN":"CLOSED";}
function operacionesFinalesProtocolo(){if(!ultimoFlujo)return[];const fisicas=[];ultimoFlujo.elementos.forEach(e=>{if(!corte.has(e.g3e_fno))return;const base=estadoBase(e),actual=estadoElemento(e);if(base!==actual)fisicas.push({id:String(e.g3e_fid),codigo:e.codigo||String(e.g3e_fid),tipo:e.tipo||"Equipo",circuito:e.circuito||"",subestacion:e.subestacion||"",base,actual,elemento:e,virtual:false});});for(const x of operacionesVirtuales.cortesLinea.values())fisicas.push({id:x.id,fidReal:x.fid,codigo:x.codigo,tipo:"Corte de linea o puente",circuito:x.circuito||"",subestacion:"",base:"CLOSED",actual:"OPEN",virtual:true,elemento:ultimoFlujo.elementos.get(String(x.fid)),punto:x.punto,nivel:x.nivel,seccionamiento:true});for(const x of operacionesVirtuales.enlaces.values())if(x.estado!=="OPEN")fisicas.push({id:x.id,codigo:x.codigo,tipo:"Interruptor provisional",circuito:`${x.circuitoA||""} / ${x.circuitoB||""}`,subestacion:"",base:"OPEN",actual:x.estado,virtual:true});for(const x of operacionesVirtuales.interruptoresNodo.values())fisicas.push({id:x.id,codigo:x.codigo,tipo:"Interruptor provisional de nodo",circuito:`${x.circuitoA||""} / ${x.circuitoB||""}`,subestacion:"",base:"CLOSED",actual:x.estado,virtual:true,nodo:x.nodo,punto:x.punto,nivel:x.nivel,fidA:x.fidA,fidB:x.fidB});for(const x of operacionesVirtuales.cruces.values())fisicas.push({id:`XC-${x.id}`,codigo:x.codigo,tipo:"Cruce aereo",circuito:x.circuito||"",subestacion:"",base:"CLOSED",actual:"OPEN",virtual:true,nodo:String(x.nodo),punto:x.punto,nivel:x.nivel,grupos:x.grupos,seccionamiento:true});for(const x of operacionesVirtuales.brakesafes.values())fisicas.push({id:x.id,fidReal:x.fid,codigo:x.codigo,tipo:"Brakesafe",circuito:x.circuito||"",subestacion:"",base:"CLOSED",actual:x.estado,virtual:true,elemento:ultimoFlujo.elementos.get(String(x.fid)),punto:x.punto,nivel:x.nivel,seccionamiento:x.estado==="OPEN"});return fisicas;}
function prioridadAperturaProtocolo(op){const fno=op.elemento?.g3e_fno;if([18800,19600,19700,19800].includes(fno))return 1.5;if(fno===19300)return 2;if(fno===20400)return 2.2;return 2.4;}function clasificarOperacionProtocolo(op,baseOverrides,flujoBase){if(op.virtual||op.actual!=="CLOSED")return{prioridad:op.actual==="OPEN"?prioridadAperturaProtocolo(op):3,pares:[]};const despues=calcularEnergia(ultimos,{...baseOverrides,[op.id]:"CLOSED"},false),pares=paresNuevosParalelo(flujoBase,despues),capaz=[18800,19700,19800].includes(Number(op.elemento?.g3e_fno)),autorizado=pares.length&&pares.every(x=>x.mismaBarra||(capaz&&paraleloAutorizado(x.a,x.b,x)));return{prioridad:autorizado?1:3,pares,bloqueoParalelo:pares.some(x=>!x.mismaBarra)&&!capaz};}
function elementoCerradoParaCamino(e,excluir=""){if(!e||String(e.g3e_fid)===String(excluir))return false;const fid=String(e.g3e_fid),st=estadoElemento(e);return !((corte.has(e.g3e_fno)&&st==="OPEN")||operacionesVirtuales.cortesLinea.has(fid)||operacionesVirtuales.brakesafes.get(fid)?.estado==="OPEN");}
function caminosCerradosHaciaFuentes(nodo,fidObjetivo=""){if(!ultimoFlujo)return[];const raices=new Set(ultimoFlujo.semillas.map(x=>String(x.fid))),cola=[],padre=new Map();for(const e of ultimoFlujo.porNodo.get(Number(nodo))||ultimoFlujo.porNodo.get(nodo)||[]){const fid=String(e.g3e_fid);if(!elementoCerradoParaCamino(e,fidObjetivo))continue;cola.push(e);padre.set(fid,null);}const encontrados=[];while(cola.length){const e=cola.shift(),fid=String(e.g3e_fid);if(raices.has(fid)){const camino=[];let k=fid;while(k){camino.push(ultimoFlujo.elementos.get(k));k=padre.get(k);}encontrados.push(camino.reverse());continue;}if(e.g3e_fno===20400)continue;for(const n of[e.nodo1,e.nodo2].filter(Boolean))for(const v of ultimoFlujo.porNodo.get(n)||[]){const vf=String(v.g3e_fid);if(padre.has(vf)||!elementoCerradoParaCamino(v,fidObjetivo)||!crucePermitePaso(n,fid,vf))continue;padre.set(vf,fid);cola.push(v);}}return encontrados.sort((a,b)=>a.length-b.length);}
function impactoAperturaEquipo(e,fidObjetivo="",op=null){const fid=String(e.g3e_fid),estadoPrevio=op?.actual==="CLOSED"?"OPEN":"CLOSED",base=fidObjetivo?{[String(fidObjetivo)]:estadoPrevio}:{},antes=calcularEnergia(ultimos,base),despues=calcularEnergia(ultimos,{...base,[fid]:"OPEN"}),usuarios=new Set();let trafos=0;for(const t of ultimoFlujo.elementos.values()){if(t.g3e_fno!==20400||estadoElemento(t)==="OPEN")continue;const tenia=(antes.procedencia.get(String(t.g3e_fid))||new Set()).size>0,luego=(despues.procedencia.get(String(t.g3e_fid))||new Set()).size>0;if(tenia&&!luego){trafos++;for(const id of usuariosActivos(t).keys())usuarios.add(id);}}return{usuarios:usuarios.size,trafos,puntaje:usuarios.size*1000+trafos};}
function dispositivoSeccionamientoEnCaminoFuente(nodo,fidObjetivo,op=null){const capaces=new Set([18800,19600,19700,19800]),opciones=new Map();for(const camino of caminosCerradosHaciaFuentes(nodo,fidObjetivo))for(let i=0;i<camino.length;i++){const e=camino[i],fid=String(e.g3e_fid);if(capaces.has(e.g3e_fno)&&estadoElemento(e)==="CLOSED"&&!opciones.has(fid))opciones.set(fid,{equipo:e,distancia:i,impacto:impactoAperturaEquipo(e,fidObjetivo,op)});}return[...opciones.values()].sort((a,b)=>a.impacto.puntaje-b.impacto.puntaje||a.distancia-b.distancia)[0]||null;}
