function usuariosConUbicacion(){const salida=[],vistos=new Set();for(const e of ultimoFlujo?.elementos.values()||[]){if(e.g3e_fno!==20400)continue;for(const u of usuariosActivos(e).values()){const lat=Number(u.gps_latitud),lng=Number(u.gps_longitud),direccion=String(u.direccion||"").trim(),id=String(u.niu||"")+"|"+lat+"|"+lng;if(!direccion||!Number.isFinite(lat)||!Number.isFinite(lng)||lat<0||lat>15||lng>-65||lng<-85||vistos.has(id))continue;vistos.add(id);salida.push({lat,lng,direccion,niu:u.niu||""});}}return salida;}
function distanciaMetros(a,b){const r=6371000,p1=a.lat*Math.PI/180,p2=b.lat*Math.PI/180,dp=(b.lat-a.lat)*Math.PI/180,dl=(b.lng-a.lng)*Math.PI/180,h=Math.sin(dp/2)**2+Math.cos(p1)*Math.cos(p2)*Math.sin(dl/2)**2;return 2*r*Math.asin(Math.sqrt(h));}
