async function completarDireccionesProtocolo(os){const usuarios=usuariosConUbicacion(),pendientes=new Map();for(const o of os){const directa=direccionGtech(o);if(directa){o.direccion=directa;o.fuenteDireccion="GTECH";continue;}const c=coordenadaProtocolo(o);if(!c){o.direccion="Dirección no disponible";o.fuenteDireccion="Sin ubicación";continue;}const usuario=usuarioMasCercano(c,usuarios);if(usuario){o.direccion=usuario.direccion;o.fuenteDireccion="Usuario cercano "+usuario.niu+" ("+Math.round(usuario.distancia)+" m)";continue;}const k=c.lat.toFixed(6)+","+c.lng.toFixed(6);o._coordenada=c;if(cacheDireccionesProtocolo.has(k)){o.direccion=cacheDireccionesProtocolo.get(k);o.fuenteDireccion="OpenStreetMap";}else{if(!pendientes.has(k))pendientes.set(k,[]);pendientes.get(k).push(o);}}for(const[k,os2]of pendientes){const c=os2[0]._coordenada;let d="Coordenadas "+c.lat.toFixed(6)+", "+c.lng.toFixed(6);try{const u="https://nominatim.openstreetmap.org/reverse?format=jsonv2&lat="+c.lat+"&lon="+c.lng+"&zoom=18&addressdetails=1&accept-language=es",r=await fetch(u);if(r.ok)d=direccionDesdeNominatim(await r.json())||d;}catch(e){}cacheDireccionesProtocolo.set(k,d);os2.forEach(o=>{o.direccion=d;o.fuenteDireccion="OpenStreetMap";});if(pendientes.size>1)await new Promise(r=>setTimeout(r,1050));}}
