function sugerirSubMedida(){if(!adminSub.value||!adminMedSub)return;const n=v=>v.normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/[^A-Z0-9]/gi,"").toUpperCase(),objetivo=n(adminSub.value),opciones=[...adminMedSub.options].filter(o=>o.value),exacta=opciones.find(o=>n(o.value)===objetivo),contenidas=opciones.filter(o=>n(o.value).includes(objetivo)||objetivo.includes(n(o.value)));adminMedSub.value=(exacta||contenidas.sort((a,b)=>Math.abs(n(a.value).length-objetivo.length)-Math.abs(n(b.value).length-objetivo.length))[0])?.value||"";}
adminSub?.addEventListener("change",()=>{sugerirSubMedida();adminConsultar.disabled=!(adminSub.value&&adminMedSub.value);});adminMedSub?.addEventListener("change",()=>{adminConsultar.disabled=!(adminSub.value&&adminMedSub.value);});
function valorMedida(m){return `${m.subestacion}|${m.interruptor}|${m.fuente}|${m.nivel_kv}`;}
function opcionesMedida(nivel,seleccion){const actual=seleccion?valorMedida(seleccion):"";return '<option value="">Sin asignar</option>'+adminDatos.medidas.filter(m=>Number(m.nivel_kv)===Number(nivel)).map(m=>`<option value="${esc(valorMedida(m))}" ${valorMedida(m)===actual?"selected":""}>${esc(m.interruptor)} · ${esc(m.fuente||"Sin fuente")}</option>`).join("");}
function selectorObjeto(obj,nivel,claseExtra=""){const exacta=obj.coincidencia_exacta,badge=exacta?'<span class="match-badge exact">Coincidencia exacta</span>':'<span class="match-badge pending">Por relacionar</span>',capacidad=obj.tipo_objeto==="BARRA"&&Number(nivel)!==13.8?`<label class="capacity-field">Capacidad del transformador (MVA)<input class="admin-capacity-input" type="number" min="0" step="0.001" value="${obj.capacidad_transformador_mva??""}" placeholder="Ej. 30"></label>`:"";return `<div class="measure-assignment ${claseExtra}" data-type="${esc(obj.tipo_objeto)}" data-fid="${obj.g3e_fid}" data-code="${esc(obj.codigo)}" data-mark="${esc(obj.marcacion||"")}" data-circuit="${esc(obj.circuito||"")}" data-level="${nivel}"><div>${badge}</div><select class="admin-measure-select">${opcionesMedida(nivel,obj.seleccion)}</select>${capacidad}</div>`;}
function valorOrigenTransformador(origen){if(!origen)return "";return origen.origen_tipo==="BARRA_GTECH"&&origen.barra_primaria_fid?`BARRA:${origen.barra_primaria_fid}`:origen.origen_tipo==="NIVEL_DIRECTO"&&origen.nivel_primario_kv?`NIVEL:${origen.nivel_primario_kv}`:"";}
function opcionesOrigenTransformador(origen){const actual=valorOrigenTransformador(origen),barras=(adminDatos?.barras||[]).filter(b=>Number(b.nivel_kv)===34.5);return `<option value="">Seleccione el origen real...</option>${barras.map(b=>`<option value="BARRA:${b.g3e_fid}" ${actual===`BARRA:${b.g3e_fid}`?"selected":""}>Barra 34,5 kV ${esc(b.codigo||b.g3e_fid)} · FID ${b.g3e_fid}</option>`).join("")}<option value="NIVEL:34.5" ${actual==="NIVEL:34.5"?"selected":""}>Directo de 34,5 kV · barra no modelada</option><option value="NIVEL:115" ${actual==="NIVEL:115"?"selected":""}>Directo de 115 kV</option><option value="NIVEL:230" ${actual==="NIVEL:230"?"selected":""}>Directo de 230 kV</option>`;}
function selectorFuncion(d,nivel){const opciones=Number(nivel)===13.8?[["ALIMENTADOR","Alimentador de 13,8 kV"],["ACOPLE","Acople de barras"],["OTRO","Otro"]]:[["LINEA_345","Línea de 34,5 kV"],["TRANSFORMADOR","Rama de transformador"],["ACOPLE","Acople de barras"],["OTRO","Otro"]],set=Number(nivel)===13.8?`<label class="set-field">SET protección de fase (A)<input class="admin-set-input" type="number" min="0" step="0.01" value="${d.set_proteccion_a??""}" placeholder="Sin SET">${d.set_origen==="EXCEL"?"<small>Valor inicial tomado del Excel DATOS Y AJUSTES</small>":""}</label>`:"";return `<label class="function-field">Función eléctrica<select class="admin-function-select">${opciones.map(([v,t])=>`<option value="${v}" ${d.funcion_electrica===v?"selected":""}>${t}</option>`).join("")}</select></label>${set}`;}
function opcionesBarrasSecundarias(actual){return '<option value="">Seleccione barra de 13,8 kV...</option>'+(adminDatos?.barras||[]).filter(b=>Number(b.nivel_kv)===13.8).map(b=>`<option value="${b.g3e_fid}" ${Number(actual)===Number(b.g3e_fid)?"selected":""}>${esc(b.codigo||b.g3e_fid)} · FID ${b.g3e_fid}</option>`).join("");}
function htmlRamalManual(r,barraFid){const tipo=r.tipo_manual||"TRANSFORMADOR",transformador=tipo==="TRANSFORMADOR";return `<div class="manual-branch-row" data-id="${r.id||""}" data-primary-fid="${barraFid}" data-manual-type="${tipo}"><div><span class="match-badge manual">Manual · no está en GTECH</span><label>Tipo de elemento<select class="manual-type" onchange="cambiarTipoManual(this)"><option value="TRANSFORMADOR" ${transformador?"selected":""}>Ramal de transformador</option><option value="CIRCUITO_345" ${!transformador?"selected":""}>Circuito / línea de 34,5 kV</option></select></label><input class="manual-branch-name" value="${esc(r.nombre||"")}" placeholder="${transformador?"Nombre del ramal, ej. AGUG11":"Nombre del circuito, ej. BUTC3"}"><label class="manual-secondary-wrap" ${transformador?"":"hidden"}>Barra de 13,8 kV alimentada<select class="manual-secondary-bar">${opcionesBarrasSecundarias(r.barra_secundaria_fid)}</select></label></div><div><label>Medida histórica asociada<select class="manual-branch-measure">${opcionesMedida(34.5,r.seleccion)}</select></label><button type="button" class="manual-remove" onclick="this.closest('.manual-branch-row').remove();actualizarCobertura()">Quitar elemento</button></div></div>`;}
function htmlRamalesBarra(b){const ramales=(adminDatos.ramales_manuales||[]).filter(r=>Number(r.barra_primaria_fid)===Number(b.g3e_fid));return `<section class="manual-branches"><div class="manual-branches-title"><div><h3>Elementos no dibujados en GTECH</h3><p>Agregue ramales de transformador o circuitos de 34,5 kV que existan operativamente.</p></div><div class="manual-add-actions"><button type="button" onclick="agregarRamalManual(${b.g3e_fid},'TRANSFORMADOR')">+ Transformador</button><button type="button" onclick="agregarRamalManual(${b.g3e_fid},'CIRCUITO_345')">+ Circuito 34,5</button></div></div><div id="manual-branches-${b.g3e_fid}">${ramales.map(r=>htmlRamalManual(r,b.g3e_fid)).join("")}</div></section>`;}
window.agregarRamalManual=(barraFid,tipo="TRANSFORMADOR")=>{document.querySelector(`#manual-branches-${barraFid}`)?.insertAdjacentHTML("beforeend",htmlRamalManual({tipo_manual:tipo},barraFid));actualizarCobertura();};
window.cambiarTipoManual=select=>{const row=select.closest(".manual-branch-row"),transformador=select.value==="TRANSFORMADOR";row.dataset.manualType=select.value;row.querySelector(".manual-secondary-wrap").hidden=!transformador;row.querySelector(".manual-branch-name").placeholder=transformador?"Nombre del ramal, ej. AGUG11":"Nombre del circuito, ej. BUTC3";if(!transformador)row.querySelector(".manual-secondary-bar").value="";actualizarCobertura();};

function renderAdmin(){const barras=adminDatos?.barras||[];adminBarras.innerHTML=barras.map((b,i)=>{const secundaria=Number(b.nivel_kv)===13.8,central345=Number(b.nivel_kv)===34.5&&b.requiere_medida_central,encabezado=secundaria?`<div class="bar-measure transformer-feed"><div><b>Transformador que alimenta esta barra de 13,8 kV</b><small>La medida seleccionada representa la salida del transformador y la entrada total a esta barra.</small><label>Origen primario real del transformador<select class="transformer-origin-select" data-secondary-fid="${b.g3e_fid}">${opcionesOrigenTransformador(b.origen_transformador)}</select></label><label>Transformador asociado<input class="transformer-group-name" data-barra-fid="${b.g3e_fid}" value="${esc(b.grupo_transformador?.nombre||`${adminDatos.subestacion}_BARRA_${b.g3e_fid}`)}" placeholder="Nombre común para agrupar barras"></label><label>Capacidad total del transformador (MVA)<input class="transformer-group-capacity" type="number" min="0" step="0.001" value="${b.grupo_transformador?.capacidad_mva??b.capacidad_transformador_mva??""}"></label></div>${selectorObjeto(b,b.nivel_kv,"bar-selector")}</div>`:central345?`<div class="bar-measure transformer-feed"><div><b>Medida central de alimentación de la barra de 34,5 kV</b><small>GTECH reporta MAIN_KV ${b.main_kv} kV, superior a 34,5 kV. Seleccione la medida de salida del transformador que alimenta esta barra.</small></div>${selectorObjeto(b,b.nivel_kv,"bar-selector")}</div>`:`<div class="bar-flow-note"><b>Barra colectora de 34,5 kV · MAIN_KV ${b.main_kv||34.5} kV</b><span>La tensión principal no es superior a 34,5 kV; no se exige medida central de transformación. Se balancea con líneas y cargas de transformación.</span></div>`;return `<article class="admin-bar"><header><div><h2>${esc(b.codigo||`Barra ${i+1}`)}</h2><span>${esc(adminDatos.subestacion)} · ${b.nivel_kv} kV · FID ${b.g3e_fid}</span></div><strong>${b.dispositivos.length} dispositivo(s)</strong></header>${encabezado}<div class="admin-device-head"><span>Dispositivo físico GTECH y función</span><span>Medida histórica asignada</span></div>${b.dispositivos.map(d=>`<div class="admin-device"><div><b>${esc(d.codigo||d.g3e_fid)}</b><span>${esc(d.tipo)}${d.circuito?` · ${esc(d.circuito)}`:""}</span><small>${esc(d.marcacion||"Sin marcación")} · FID ${d.g3e_fid}</small>${selectorFuncion(d,b.nivel_kv)}</div>${selectorObjeto(d,b.nivel_kv)}</div>`).join("")||'<p class="admin-empty">GTECH no reportó interruptores o transformadores conectados directamente a esta barra.</p>'}${Number(b.nivel_kv)===34.5?htmlRamalesBarra(b):""}</article>`;}).join("")||'<div class="analysis-empty"><h2>Sin barras</h2><p>No se encontraron barras GTECH de 13,8 o 34,5 kV.</p></div>';adminGuardar.disabled=!barras.length;actualizarCobertura();}
function actualizarCobertura(){if(!adminDatos)return;const objetos=[...document.querySelectorAll("#admin-barras .measure-assignment")],asignados=objetos.filter(x=>x.querySelector("select")?.value).length,exactos=objetos.filter(x=>x.querySelector(".exact")).length,barras=adminDatos.barras.length,alimentadores=objetos.filter(x=>x.dataset.type==="ALIMENTADOR").length,ramales=[...document.querySelectorAll(".manual-branch-row")],ramalesAsignados=ramales.filter(x=>x.querySelector(".manual-branch-name")?.value&&(x.dataset.manualType==="CIRCUITO_345"||x.querySelector(".manual-secondary-bar")?.value)&&x.querySelector(".manual-branch-measure")?.value).length,circuitosManuales=ramales.filter(x=>x.dataset.manualType==="CIRCUITO_345").length;document.querySelector("#admin-cobertura").innerHTML=`<article><span>Barras GTECH</span><b>${barras}</b></article><article><span>Dispositivos conectados</span><b>${alimentadores}</b></article><article><span>Ramales de transformador</span><b>${ramales.length-circuitosManuales}</b></article><article><span>Circuitos 34,5 manuales</span><b>${circuitosManuales}</b></article><article><span>Coincidencias exactas</span><b>${exactos}</b></article><article><span>Asignaciones seleccionadas</span><b>${asignados+ramalesAsignados}</b></article><article><span>Pendientes</span><b>${objetos.length-asignados+ramales.length-ramalesAsignados}</b></article>`;}
adminBarras?.addEventListener("change",event=>{if(event.target.matches(".admin-measure-select"))actualizarCobertura();});
adminConsultar?.addEventListener("click",async()=>{adminConsultar.disabled=true;adminGuardar.disabled=true;adminStatus.textContent="Consultando barras y dispositivos físicos en GTECH...";adminStatus.classList.add("active");try{const q=new URLSearchParams({subestacion:adminSub.value,medida_subestacion:adminMedSub.value}),r=await fetch(`${APP.adminBarras}?${q}`),d=await r.json();if(!r.ok)throw new Error(d.error||"No fue posible consultar");adminDatos=d;renderAdmin();adminStatus.textContent=`${d.barras.length} barra(s) encontradas. Las coincidencias exactas están preseleccionadas; revise y guarde.`;}catch(error){adminStatus.textContent=error.message;adminBarras.innerHTML="";}finally{adminStatus.classList.remove("active");adminConsultar.disabled=false;}});
adminGuardar?.addEventListener("click",async()=>{const asignaciones=[...document.querySelectorAll("#admin-barras .measure-assignment")].map(row=>{const value=row.querySelector("select").value,parts=value?value.split("|"):null,device=row.closest(".admin-device");return{tipo_objeto:row.dataset.type,gtech_fid:Number(row.dataset.fid),gtech_codigo:row.dataset.code,gtech_marcacion:row.dataset.mark,gtech_circuito:row.dataset.circuit,subestacion:adminDatos.subestacion,nivel_kv:Number(row.dataset.level),funcion_electrica:device?.querySelector(".admin-function-select")?.value||(row.dataset.type==="BARRA"?"ENTRADA_TRANSFORMADOR":""),set_proteccion_a:device?.querySelector(".admin-set-input")?.value||null,capacidad_transformador_mva:row.querySelector(".admin-capacity-input")?.value||null,medida:parts?{subestacion:parts[0],interruptor:parts[1],fuente:parts[2],nivel_kv:Number(parts[3])}:null};}),relaciones_transformacion=[...document.querySelectorAll(".transformer-origin-select")].map(x=>{const [tipo,valor]=x.value?x.value.split(":"):[];return{barra_secundaria_fid:Number(x.dataset.secondaryFid),origen_tipo:tipo==="BARRA"?"BARRA_GTECH":tipo==="NIVEL"?"NIVEL_DIRECTO":"",barra_primaria_fid:tipo==="BARRA"?Number(valor):null,nivel_primario_kv:tipo==="NIVEL"?Number(valor):null,subestacion:adminDatos.subestacion};}),grupos_transformacion=[...document.querySelectorAll(".transformer-group-name")].map(x=>({barra_fid:Number(x.dataset.barraFid),nombre:x.value.trim(),capacidad_mva:x.closest(".transformer-feed")?.querySelector(".transformer-group-capacity")?.value||null,subestacion:adminDatos.subestacion})),ramales_manuales=[...document.querySelectorAll(".manual-branch-row")].map(row=>{const value=row.querySelector(".manual-branch-measure").value,parts=value?value.split("|"):null;return{id:row.dataset.id?Number(row.dataset.id):null,tipo_manual:row.dataset.manualType||"TRANSFORMADOR",nombre:row.querySelector(".manual-branch-name").value.trim(),barra_primaria_fid:Number(row.dataset.primaryFid),barra_secundaria_fid:row.querySelector(".manual-secondary-bar").value?Number(row.querySelector(".manual-secondary-bar").value):null,subestacion:adminDatos.subestacion,medida:parts?{subestacion:parts[0],interruptor:parts[1],fuente:parts[2],nivel_kv:Number(parts[3])}:null};}).filter(x=>x.nombre);adminGuardar.disabled=true;adminStatus.textContent="Guardando asignaciones...";try{const r=await fetch(APP.adminGuardar,{method:"POST",headers:{"Content-Type":"application/json","X-CSRFToken":APP.csrf},body:JSON.stringify({subestacion:adminDatos.subestacion,asignaciones,relaciones_transformacion,grupos_transformacion,ramales_manuales})}),d=await r.json();if(!r.ok)throw new Error(d.error||"No fue posible guardar");adminStatus.textContent=`${d.guardadas} objetos GTECH y ${d.ramales} elemento(s) manual(es) procesados correctamente.`;}catch(error){adminStatus.textContent=error.message;}finally{adminGuardar.disabled=false;}});
const parallelCatalog=document.querySelector("#parallel-catalog"),parallelStatus=document.querySelector("#parallel-status"),parallelAdd=document.querySelector("#parallel-add"),parallelSave=document.querySelector("#parallel-save");
function opcionesSubestacionesParalelo(valor=""){const items=[...document.querySelectorAll("#sub option")].filter(x=>x.value);return '<option value="">Seleccione...</option>'+items.map(x=>`<option value="${esc(x.value)}" ${x.value===valor?"selected":""}>${esc(x.textContent)}</option>`).join("");}
async function cargarCeldasFilaParalelo(row,lado,seleccion=null){const sub=row.querySelector(`.parallel-sub-${lado}`).value,select=row.querySelector(`.parallel-cell-${lado}`);select.disabled=true;select.innerHTML='<option value="">Consultando...</option>';if(!sub){select.innerHTML='<option value="">Seleccione subestacion...</option>';return;}try{const r=await fetch(`${APP.circuitos}?subestacion=${encodeURIComponent(sub)}`),d=await r.json();if(!r.ok)throw new Error(d.error||"Error");select.innerHTML='<option value="">Seleccione celda...</option>'+d.circuitos.map(x=>`<option value="${x.g3e_fid}" data-code="${esc(x.codigo)}" data-level="${x.tension}" ${String(x.g3e_fid)===String(seleccion?.fid||"")?"selected":""}>[${esc(x.tension)} kV] ${esc(x.codigo)}</option>`).join("");select.disabled=false;}catch(error){select.innerHTML='<option value="">No fue posible consultar</option>';parallelStatus.textContent=error.message;}}
function agregarFilaParalelo(item={}){const row=document.createElement("div");row.className="parallel-row";row.dataset.id=item.id||"";row.innerHTML=`<div><label>Subestación A<select class="parallel-sub-a">${opcionesSubestacionesParalelo(item.subestacion_a)}</select></label><label>Línea / celda A<select class="parallel-cell-a" disabled></select></label></div><div><label>Subestación B<select class="parallel-sub-b">${opcionesSubestacionesParalelo(item.subestacion_b)}</select></label><label>Línea / celda B<select class="parallel-cell-b" disabled></select></label></div><label class="parallel-note">Observacion<input type="text" value="${esc(item.observacion||"")}" placeholder="Condiciones operativas del paralelo"></label><label class="parallel-active"><input type="checkbox" ${item.activo!==false?"checked":""}> Activo</label><button type="button" class="parallel-remove">Quitar</button>`;parallelCatalog.appendChild(row);row.querySelector(".parallel-sub-a").addEventListener("change",()=>cargarCeldasFilaParalelo(row,"a"));row.querySelector(".parallel-sub-b").addEventListener("change",()=>cargarCeldasFilaParalelo(row,"b"));row.querySelector(".parallel-remove").onclick=()=>row.remove();cargarCeldasFilaParalelo(row,"a",{fid:item.celda_a_fid});cargarCeldasFilaParalelo(row,"b",{fid:item.celda_b_fid});}
async function renderParalelosAdmin(){parallelCatalog.innerHTML="";parallelStatus.textContent="Consultando autorizaciones...";await cargarParalelosPermitidos();paralelosPermitidos.forEach(agregarFilaParalelo);if(!paralelosPermitidos.length)agregarFilaParalelo();parallelStatus.textContent=`${paralelosPermitidos.length} paralelo(s) registrado(s).`;}
parallelAdd?.addEventListener("click",()=>agregarFilaParalelo());parallelSave?.addEventListener("click",async()=>{try{const items=[...parallelCatalog.querySelectorAll(".parallel-row")].map(row=>{const sa=row.querySelector(".parallel-sub-a"),sb=row.querySelector(".parallel-sub-b"),ca=row.querySelector(".parallel-cell-a"),cb=row.querySelector(".parallel-cell-b"),oa=ca.options[ca.selectedIndex],ob=cb.options[cb.selectedIndex];if(!sa.value||!sb.value||!ca.value||!cb.value)throw new Error("Complete las dos celdas de cada autorizacion.");if(oa.dataset.level!==ob.dataset.level)throw new Error("Las celdas autorizadas deben tener el mismo nivel de tension.");return{id:row.dataset.id||null,subestacion_a:sa.value,celda_a_fid:Number(ca.value),celda_a_codigo:oa.dataset.code,subestacion_b:sb.value,celda_b_fid:Number(cb.value),celda_b_codigo:ob.dataset.code,nivel_kv:Number(oa.dataset.level),observacion:row.querySelector(".parallel-note input").value.trim(),activo:row.querySelector(".parallel-active input").checked};}),r=await fetch(APP.adminGuardarParalelos,{method:"POST",headers:{"Content-Type":"application/json","X-CSRFToken":APP.csrf},body:JSON.stringify({paralelos:items})}),d=await r.json();if(!r.ok)throw new Error(d.error||"No fue posible guardar");parallelStatus.textContent=`${d.guardados} paralelo(s) guardado(s).`;await renderParalelosAdmin();}catch(error){parallelStatus.textContent=error.message;}});
async function cargarConfiguracionScada(){const input=document.querySelector("#scada-data-dir"),status=document.querySelector("#scada-folder-status"),guardar=document.querySelector("#scada-folder-save"),seleccionar=document.querySelector("#scada-folder-select");if(!input||!status)return;status.textContent="Consultando configuración local...";try{const r=await fetch(APP.adminScada),d=await r.json();if(!r.ok)throw new Error(d.error||"No fue posible consultar la configuración.");input.value=d.ruta||"";input.disabled=Boolean(d.impuesta);guardar.disabled=Boolean(d.impuesta);seleccionar.disabled=Boolean(d.impuesta);status.textContent=d.mensaje+(d.impuesta?" Ruta administrada mediante variable de entorno.":"");}catch(error){status.textContent=error.message;}}
async function guardarConfiguracionScada(seleccionar=false){const input=document.querySelector("#scada-data-dir"),status=document.querySelector("#scada-folder-status"),guardar=document.querySelector("#scada-folder-save"),botonSeleccionar=document.querySelector("#scada-folder-select");guardar.disabled=true;botonSeleccionar.disabled=true;status.textContent=seleccionar?"Abra el selector de Windows...":"Validando acceso a la carpeta...";try{const r=await fetch(APP.adminSeleccionarScada,{method:"POST",headers:{"Content-Type":"application/json","X-CSRFToken":APP.csrf},body:JSON.stringify(seleccionar?{seleccionar:true}:{ruta:input.value.trim()})}),d=await r.json();if(!r.ok)throw new Error(d.error||"No fue posible guardar la carpeta.");if(d.cancelado){status.textContent="Selección cancelada. La configuración anterior no cambió.";return;}input.value=d.ruta||input.value;status.textContent=d.mensaje+" La ruta quedó guardada solamente para este usuario.";}catch(error){status.textContent=error.message;}finally{guardar.disabled=false;botonSeleccionar.disabled=false;}}
document.querySelector("#scada-folder-save")?.addEventListener("click",()=>guardarConfiguracionScada(false));document.querySelector("#scada-folder-select")?.addEventListener("click",()=>guardarConfiguracionScada(true));
document.querySelectorAll("[data-admin-tab]").forEach(button=>button.addEventListener("click",()=>{document.querySelectorAll("[data-admin-tab]").forEach(x=>x.classList.toggle("active",x===button));for(const tab of ["asignaciones","cobertura","scada","calibres","reglas","paralelos","estados"])document.querySelector(`#admin-tab-${tab}`).hidden=button.dataset.adminTab!==tab;if(button.dataset.adminTab==="scada")cargarConfiguracionScada();if(button.dataset.adminTab==="calibres")cargarCatalogoConductores();if(button.dataset.adminTab==="paralelos")renderParalelosAdmin();if(button.dataset.adminTab==="reglas")cargarReglasManiobraAdmin();}));

renderLeyenda(null);

let catalogoConductores=[];const conductorCatalog=document.querySelector("#conductor-catalog"),conductorFilter=document.querySelector("#conductor-filter"),conductorSave=document.querySelector("#conductor-save");
async function cargarCatalogoConductores(){if(catalogoConductores.length){renderCatalogoConductores();return;}conductorCatalog.innerHTML='<div class="chart-message">Cargando catálogo CENS...</div>';try{const r=await fetch(APP.adminCalibres),d=await r.json();if(!r.ok)throw new Error(d.error||"No fue posible cargar el catálogo");catalogoConductores=d.conductores;renderCatalogoConductores();}catch(error){conductorCatalog.innerHTML=`<div class="chart-message error">${esc(error.message)}</div>`;}}
function campoCatalogo(x,campo,clase="",step="0.000001",placeholder="Pendiente"){return `<input class="conductor-param ${clase}" data-field="${campo}" type="${campo==="fabricante"||campo==="fuente_tecnica"?"text":"number"}" ${campo==="fabricante"||campo==="fuente_tecnica"?"":`min="0" step="${step}"`} value="${esc(x[campo]??"")}" placeholder="${placeholder}">`;}
function renderCatalogoConductores(){const filtro=(conductorFilter?.value||"").trim().toUpperCase(),items=catalogoConductores.filter(x=>!filtro||`${x.codigo} ${x.material} ${x.calibre} ${x.descripcion} ${x.familia} ${x.fabricante}`.toUpperCase().includes(filtro));conductorCatalog.innerHTML=`<div class="conductor-count">${items.length} de ${catalogoConductores.length} referencias CENS · parámetros editables para ampacidad y perfil de tensión</div><div class="conductor-table-wrap"><table class="conductor-table profile-table"><thead><tr><th>Referencia / clasificación</th><th>Fuente y trazabilidad</th><th>Ampacidad (A)</th><th>Resistividad<br>Ω·mm²/m</th><th>R operación<br>Ω/km</th><th>X 60 Hz<br>Ω/km</th><th>GMR<br>mm</th><th>Diámetro<br>mm</th><th>Temp.<br>°C</th></tr></thead><tbody>${items.map(x=>`<tr data-code="${esc(x.codigo)}"><td><b>${esc(x.codigo)}</b><small>${esc(x.material||"—")} · ${esc(x.calibre||"—")} · ${esc(x.seccion_mm2??"—")} mm²</small><small>${esc(x.descripcion||"")}</small><small>${esc(x.familia||"")} · ${esc(x.tension_nominal_kv??"—")} kV</small></td><td>${campoCatalogo(x,"fabricante","wide","1","Fuente fabricante")}${campoCatalogo(x,"fuente_tecnica","wide","1","Ficha, norma o URL")}<small><b>Confianza:</b> ${esc(x.confianza||"Sin clasificar")}</small><small>${esc(x.origen_ampacidad||"")}</small><small>${esc(x.origen_parametros||"")}</small>${x.observaciones?`<small>${esc(x.observaciones)}</small>`:""}</td><td>${campoCatalogo(x,"ampacidad_a","","0.01")}</td><td>${campoCatalogo(x,"resistividad_ohm_mm2_m")}</td><td>${campoCatalogo(x,"resistencia_ohm_km")}</td><td>${campoCatalogo(x,"reactancia_ohm_km")}</td><td>${campoCatalogo(x,"gmr_mm")}</td><td>${campoCatalogo(x,"diametro_mm","","0.0001")}</td><td>${campoCatalogo(x,"temperatura_referencia_c","","0.01")}</td></tr>`).join("")}</tbody></table></div>`;}
