document.querySelector("#rule-current-save")?.addEventListener("click",async()=>{const button=document.querySelector("#rule-current-save"),status=document.querySelector("#rule-current-status"),apertura=Number(document.querySelector("#rule-current-open").value),cierre=Number(document.querySelector("#rule-current-close").value),payload={corriente_max_apertura_aisladero_a:apertura,corriente_max_cierre_aisladero_a:cierre,usuarios_totales_cens:Number(document.querySelector("#rule-total-users")?.value||0),maniobra_inicio_desenergizacion:document.querySelector("#rule-text-start-off")?.value.trim(),maniobra_fin_desenergizacion:document.querySelector("#rule-text-end-off")?.value.trim(),maniobra_inicio_energizacion:document.querySelector("#rule-text-start-on")?.value.trim(),maniobra_fin_energizacion:document.querySelector("#rule-text-end-on")?.value.trim()};if(!Number.isFinite(apertura)||!Number.isFinite(cierre)||apertura<0||cierre<0){status.textContent="Ingrese corrientes válidas y no negativas.";return;}if(Object.entries(payload).some(([k,v])=>k.startsWith("maniobra_")&&!v)){status.textContent="Complete los cuatro textos automáticos del protocolo.";return;}button.disabled=true;status.textContent="Guardando límites y textos...";try{const r=await fetch(APP.adminGuardarReglasManiobra,{method:"POST",headers:{"Content-Type":"application/json","X-CSRFToken":APP.csrf},body:JSON.stringify(payload)}),d=await r.json();if(!r.ok)throw new Error(d.error||"No fue posible guardar.");reglasManiobra=d;status.textContent="Límites y textos automáticos guardados.";}catch(error){status.textContent=error.message;}finally{button.disabled=false;}});cargarReglasManiobraAdmin();cargarParalelosPermitidos();
