function pasoInstitucional(texto,codigo){return{institucional:true,texto:String(texto||""),codigo,accion:"Realizar",actual:"ACTION",base:"ACTION",tipo:"Coordinación y seguridad",subestacion:"No aplica",circuito:"No aplica",nivel:"No aplica",direccion:"No aplica",fechaTexto:fechaProtocolo(),manual:{}};}
