function protocoloEnergizacion(items){const base=(items||[]).filter(x=>!x.institucional);return[pasoInstitucional(reglasManiobra.maniobra_inicio_energizacion,"CONTROL-INICIO-ENE"),...base,pasoInstitucional(reglasManiobra.maniobra_fin_energizacion,"CONTROL-FIN")];}
function descripcionParaleloManiobra(pares){if(!pares?.length)return"";return pares.map(p=>{const a=String(p.a||"").split("@"),b=String(p.b||"").split("@");return" Celdas puestas en paralelo por este cierre: "+(a[0]||p.a)+" ("+(a[1]||"subestacion no identificada")+") ↔ "+(b[0]||p.b)+" ("+(b[1]||"subestacion no identificada")+")"+(p.mismaBarra?", ambas sobre la barra fisica "+(p.barraA||"no identificada"):"")+".";}).join(" ");}
function datosFilaProtocolo(o,normalizar=false){if(o.institucional)return{accion:"Realizar",subestacion:"No aplica",celda:"No aplica",nivel:"No aplica",direccion:"No aplica",dispositivo:o.codigo,maniobra:o.texto};const accion=o.accion||(normalizar?nombreAccion(o.base):nombreAccion(o.actual)),subestacion=o.subestacion||o.elemento?.subestacion||"Sin dato",celda=o.circuito||o.elemento?.circuito||"Sin dato",nivel=o.nivel||o.elemento?._nivel_kv||"Sin dato",direccion=o.direccion||"Dirección no disponible",tipo=String(o.tipo||"dispositivo").toLowerCase(),pares=o.pares?.length?o.pares:o.manual?.paresParalelo||[],detalleParalelo=String(accion).toUpperCase()==="CERRAR"?descripcionParaleloManiobra(pares):"",maniobra=(o.manual?.grupos?accion+" cruce aéreo separando la conexión entre "+codigoParesCruce(o.manual.grupos)+" de nivel de tensión "+nivel+" kV de la celda "+celda+" en la dirección "+direccion+".":accion+" "+(tipo==="equipo"?"dispositivo":tipo)+" "+o.codigo+" de nivel de tensión "+nivel+" kV de la celda "+celda+" en la dirección "+direccion+".")+detalleParalelo;return{accion,subestacion,celda,nivel,direccion,dispositivo:o.codigo,maniobra};}
function tablaProtocolo(os,n=false){const items=n?protocoloEnergizacion(os):protocoloDesenergizacion(os),cab='<div class="protocol-table-wrap"><table class="protocol-table"><thead><tr><th>#</th><th>Fecha</th><th>Subestación</th><th>Celda</th><th>Dispositivo</th><th>Estado</th><th>Dirección aproximada</th><th>Maniobra</th></tr></thead><tbody>';return cab+items.map((o,i)=>{const d=datosFilaProtocolo(o,n);return`<tr class="${o.institucional?"institutional-step":""}"><td>${i+1}</td><td>${esc(o.fechaTexto||fechaProtocolo())}</td><td>${esc(d.subestacion)}</td><td>${esc(d.celda)}</td><td><b>${esc(d.dispositivo)}</b></td><td><b>${esc(d.accion)}</b></td><td>${esc(d.direccion)}</td><td>${esc(d.maniobra)}</td></tr>`;}).join("")+"</tbody></table></div>";}
function tablaManiobrasManuales(items,conexion=false){const lista=conexion?protocoloEnergizacion(items):protocoloDesenergizacion(items),cab='<div class="protocol-table-wrap"><table class="protocol-table"><thead><tr><th>#</th><th>Fecha</th><th>Subestación</th><th>Celda</th><th>Dispositivo</th><th>Estado</th><th>Dirección aproximada</th><th>Maniobra</th></tr></thead><tbody>';return cab+lista.map((o,i)=>{const d=datosFilaProtocolo(o,false);return`<tr class="${o.institucional?"institutional-step":""}"><td>${i+1}</td><td>${esc(o.fechaTexto||fechaProtocolo())}</td><td>${esc(d.subestacion)}</td><td>${esc(d.celda)}</td><td><b>${esc(d.dispositivo)}</b></td><td><b>${esc(d.accion)}</b></td><td>${esc(d.direccion)}</td><td>${esc(d.maniobra)}</td></tr>`;}).join("")+"</tbody></table></div>";}
